module mpc_controller (
    input wire clk,
    input wire rst,
    input wire [7:0] setpoint,
    input wire [7:0] current_output,
    output reg [7:0] new_output
);
    reg [7:0] error;
    reg [7:0] control_adjustment;
    parameter PROPORTIONAL_GAIN = 8'd2;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            new_output <= 8'b0;
        end else begin
            error <= setpoint - current_output;
            control_adjustment <= error * PROPORTIONAL_GAIN;
            new_output <= current_output + control_adjustment;
        end
    end
endmodule

