module dma_controller (
    input clk,
    input rst,
    input start_ch1,
    input start_ch2,
    output reg done_ch1,
    output reg done_ch2,
    output reg [7:0] data_out_ch1,
    output reg [7:0] data_out_ch2
);
    reg [7:0] src_address_ch1, dest_address_ch1;
    reg [7:0] src_address_ch2, dest_address_ch2;
    reg [1:0] state;

    localparam IDLE = 2'b00, TRANSFER_CH1 = 2'b01, TRANSFER_CH2 = 2'b10, DONE = 2'b11;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= IDLE;
            done_ch1 <= 0;
            done_ch2 <= 0;
            data_out_ch1 <= 8'b0;
            data_out_ch2 <= 8'b0;
        end else begin
            case (state)
                IDLE: begin
                    if (start_ch1) begin
                        src_address_ch1 <= 8'h01; // Example source address
                        dest_address_ch1 <= 8'hA0; // Example destination address
                        state <= TRANSFER_CH1;
                    end else if (start_ch2) begin
                        src_address_ch2 <= 8'h02; // Example source address
                        dest_address_ch2 <= 8'hB0; // Example destination address
                        state <= TRANSFER_CH2;
                    end
                end
                TRANSFER_CH1: begin
                    data_out_ch1 <= src_address_ch1; // Simulate data transfer
                    done_ch1 <= 1;
                    state <= DONE;
                end
                TRANSFER_CH2: begin
                    data_out_ch2 <= src_address_ch2; // Simulate data transfer
                    done_ch2 <= 1;
                    state <= DONE;
                end
                DONE: begin
                    if (done_ch1 && done_ch2) begin
                        state <= IDLE;
                        done_ch1 <= 0;
                        done_ch2 <= 0;
                    end
                end
            endcase
        end
    end
endmodule

