module min_heap (
    input wire clk,
    input wire rst,
    input wire insert,
    input wire [7:0] value,
    input wire extract,
    output reg [7:0] min_value,
    output reg empty
);

    reg [7:0] heap [0:15]; // Heap array with a maximum of 16 elements
    reg [3:0] size; // Current size of the heap

    initial begin
        size = 0;
        empty = 1;
    end

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            size <= 0;
            empty <= 1;
        end else begin
            if (insert) begin
                if (size < 16) begin
                    heap[size] <= value; // Insert value at the end
                    size <= size + 1;
                    empty <= (size + 1 == 0);
                    // Heapify up
                    // Here we would typically implement the bubble up logic
                end
            end
            if (extract && size > 0) begin
                min_value <= heap[0]; // Get minimum value
                heap[0] <= heap[size - 1]; // Replace root with the last element
                size <= size - 1; // Decrease size
                empty <= (size == 0);
                // Heapify down
                // Here we would typically implement the bubble down logic
            end
        end
    end
endmodule

