module serializer_16bit (  
    input clk,  
    input rst,  
    input [15:0] parallel_in,  
    output reg serial_out  
);  
    reg [15:0] shift_reg;  
    reg [3:0] bit_count;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            shift_reg <= 16'b0;  
            serial_out <= 1'b0;  
            bit_count <= 4'b0;  
        end else begin  
            if (bit_count < 16) begin  
                serial_out <= shift_reg[0];  
                shift_reg <= {1'b0, shift_reg[15:1]};  
                bit_count <= bit_count + 1;  
            end else begin  
                serial_out <= 1'b0;  
            end  
        end  
    end  

    always @(posedge clk) begin  
        if (bit_count == 0)  
            shift_reg <= parallel_in;  
    end  
endmodule

