module fractional_n_pll (
    input wire ref_clk,
    input wire [7:0] fractional_ratio,
    input wire reset,
    output reg pll_clk,
    output reg locked
);
    reg [31:0] count;
    reg [31:0] target;

    always @(posedge ref_clk or posedge reset) begin
        if (reset) begin
            count <= 32'b0;
            pll_clk <= 1'b0;
            locked <= 1'b0;
        end else begin
            target <= fractional_ratio * 100; // Example scaling factor for simulation
            if (count < target) begin
                count <= count + 1;
            end else begin
                count <= 32'b0;
                pll_clk <= ~pll_clk; // Toggle clock
                locked <= 1'b1; // Assume locked after some cycles
            end
        end
    end
endmodule

