module pll_4x(  
    input wire clk_in,  
    input wire reset,  
    output reg clk_out  
);  

    reg [1:0] phase;  
    reg [3:0] vco_count;  
    reg [1:0] control_signal;  

    always @(posedge clk_in or posedge reset) begin  
        if (reset) begin  
            phase <= 2'b00;  
            vco_count <= 4'b0000;  
            clk_out <= 0;  
        end else begin  
            phase <= phase + 1;  
            if (phase == 2'b11) begin  
                clk_out <= ~clk_out;  
            end  
        end  
    end  

    always @(posedge clk_in) begin  
        vco_count <= vco_count + 1;  
        if (vco_count == 4'b0011) begin  
            control_signal <= 2'b10;  
        end else begin  
            control_signal <= 2'b00;  
        end  
    end  
endmodule

