module adaptive_lms_filter #(parameter N = 5, parameter STEP_SIZE = 8'b00000001) (  
    input clk,  
    input rst,  
    input [15:0] x, // input signal  
    input [15:0] d, // desired signal  
    output reg [15:0] y // output signal  
);  
    reg [15:0] w [0:N-1]; // weights  
    reg [15:0] e; // error signal  
    integer i;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            for (i = 0; i < N; i = i + 1)  
                w[i] <= 16'b0;  
            y <= 16'b0;  
            e <= 16'b0;  
        end else begin  
            // Calculate output  
            y <= 16'b0;  
            for (i = 0; i < N; i = i + 1)  
                y <= y + (w[i] * x);  

            // Calculate error  
            e <= d - y;  

            // Update weights  
            for (i = 0; i < N; i = i + 1)  
                w[i] <= w[i] + (STEP_SIZE * e * x);  
        end  
    end  
endmodule

