module i2c_master (
    input wire clk,
    input wire start,
    input wire stop,
    input wire [7:0] data_in,
    output reg scl,
    output reg sda
);
    reg [3:0] state;
    parameter IDLE = 4'b0000, START = 4'b0001, DATA = 4'b0010, STOP = 4'b0011;
    integer i;

    always @(posedge clk) begin
        case (state)
            IDLE: begin
                scl <= 1;
                sda <= 1;
                if (start) begin
                    state <= START;
                end
            end
            START: begin
                sda <= 0; // Start condition
                state <= DATA;
                scl <= 0;
            end
            DATA: begin
                for (i = 0; i < 8; i = i + 1) begin
                    sda <= data_in[7-i]; // Send MSB first
                    scl <= 1;
                    scl <= 0;
                end
                state <= STOP;
            end
            STOP: begin
                sda <= 0; // Prepare for stop condition
                scl <= 1;
                sda <= 1; // Stop condition
                state <= IDLE;
            end
            default: state <= IDLE;
        endcase
    end
endmodule

