module comparator_32bit (
    input [31:0] A,
    input [31:0] B,
    output reg A_gt_B,
    output reg A_eq_B,
    output reg A_lt_B
);

    always @* begin
        A_gt_B = 0;
        A_eq_B = 0;
        A_lt_B = 0;

        if (A > B) begin
            A_gt_B = 1;
        end else if (A == B) begin
            A_eq_B = 1;
        end else begin
            A_lt_B = 1;
        end
    end
endmodule

