module freq_recovery(
    input wire clk_in,
    input wire reset,
    output reg clk_out
);
    reg [1:0] state;
    parameter S0 = 2'b00, S1 = 2'b01, S2 = 2'b10, S3 = 2'b11;

    always @(posedge clk_in or posedge reset) begin
        if (reset) begin
            state <= S0;
            clk_out <= 0;
        end else begin
            case (state)
                S0: begin
                    clk_out <= 1;
                    state <= S1;
                end
                S1: begin
                    clk_out <= 0;
                    state <= S2;
                end
                S2: begin
                    clk_out <= 1;
                    state <= S3;
                end
                S3: begin
                    clk_out <= 0;
                    state <= S0;
                end
            endcase
        end
    end
endmodule

