module johnson_counter (
    input clk,
    input rst,
    output [4:0] q
);
    reg [4:0] q_reg;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            q_reg <= 5'b00000;
        end else begin
            q_reg <= {~q_reg[0], q_reg[4:1]};
