module deserializer_16bit (  
    input wire clk,  
    input wire rst,  
    input wire serial_in,  
    output reg [15:0] parallel_out  
);  
    reg [3:0] bit_count;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            parallel_out <= 16'b0;  
            bit_count <= 4'b0;  
        end else begin  
            parallel_out <= {parallel_out[14:0], serial_in};  
            if (bit_count < 15)  
                bit_count <= bit_count + 1;  
            else  
                bit_count <= 4'b0;  
        end  
    end  
endmodule

