module kalman_filter(
    input clk,
    input rst,
    input signed [15:0] pos_sensor,  // position sensor input
    input signed [15:0] vel_sensor,  // velocity sensor input
    output reg signed [15:0] pos_est   // estimated position output
);
    reg signed [15:0] prev_pos_est;
    reg signed [15:0] kalman_gain;

    initial begin
        pos_est = 0;
        prev_pos_est = 0;
        kalman_gain = 16'h0001;  // Fixed Kalman gain for simplicity
    end

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            pos_est <= 0;
            prev_pos_est <= 0;
        end else begin
            // Kalman filter update step
            pos_est <= prev_pos_est + kalman_gain * (pos_sensor - prev_pos_est);
            prev_pos_est <= pos_est;
        end
    end
endmodule

