module md5_hash (
    input wire clk,
    input wire rst,
    input wire [31:0] data_in,
    output reg [31:0] hash_out
);
    reg [31:0] temp_hash;
    reg [31:0] constant = 32'hAABBCCDD;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            hash_out <= 32'h00000000;
            temp_hash <= 32'h00000000;
