module spi_master (  
    input wire clk,  
    input wire start,  
    input wire [7:0] data_in,  
    output reg mosi,  
    output reg sclk  
);  
    reg [2:0] bit_cnt;  
    reg [7:0] shift_reg;  
    reg state; // 0: idle, 1: transmitting  

    always @(posedge clk) begin  
        if (start) begin  
            shift_reg <= data_in;  
            bit_cnt <= 3'b000;  
            state <= 1;  
        end else if (state) begin  
            sclk <= ~sclk; // Toggle clock  
            if (sclk) begin  
                mosi <= shift_reg[7]; // Send MSB first  
                shift_reg <= {shift_reg[6:0], 1'b0}; // Shift left  
                bit_cnt <= bit_cnt + 1;  
                if (bit_cnt == 3'b111) begin  
                    state <= 0; // Stop transmitting after 8 bits  
                end  
            end  
        end else begin  
            sclk <= 0;  
            mosi <= 0;  
        end  
    end  
endmodule

